        y.len() > 0,
        x.len() < 1000000,
        y.len() < 1000000,
    ensures
        b.len() == x.len() + y.len(),
        forall|i: int| 0 <= i < x.len() ==> b[i] == x[i],
        forall|i: int| x.len() <= i < x.len() + y.len() ==> b[i] == y[i - x.len()],
{

answer:
assert(x.len() + y.len() < i32::MAX as usize);
    let mut b = Vec::with_capacity(x.len() + y.len());
    for i in 0..x.len()
        invariant
            0 <= i && i <= x.len(),
            b.len() == i,
            forall|j: int| 0 <= j < i ==> b[j] == x[j],
    {
        b.push(x[i]);
