        invariant
            0 <= i && i <= y.len(),
            b.len() == x.len() + i,
            forall|j: int| 0 <= j < x.len() ==> b[j] == x[j],
            forall|j: int| x.len() <= j < x.len() + i ==> b[j] == y[j - x.len()],
