use vstd::prelude::*;

verus! {

fn tangent(r: &[u64], x: &[u64]) -> (b: bool)
    requires
        x.len() > 0,
        r.len() < 1000, // added relaxation to prevent overflow
        x.len() < 1000, // added relaxation to prevent overflow
        forall|i: nat, j: nat| 0 <= i <= j < x.len() ==> x[i as int] <= x[j as int],
        forall|i: nat, j: nat| (0 <= i < r.len() && 0 <= j < x.len()) ==> (r[i as int] >= 0 && x[j as int] >= 0),
    ensures
        !b ==> forall|i: nat, j: nat| 0 <= i < r.len() && 0 <= j < x.len() ==> r[i as int] != x[j as int],
        b ==> exists|i: nat, j: nat| 0 <= i < r.len() && 0 <= j < x.len() && r[i as int] == x[j as int],
{

answer:
let mut temp_b: bool = false;
    let mut tangent_missing: bool = false;
    let mut k: usize = 0;
    let mut l: usize = 0;
    while k < r.len() && !temp_b
        invariant
            0 <= k && k <= r.len(),
            temp_b ==> exists|i: nat, j: nat| 0 <= i < r.len() && 0 <= j < x.len() && r[i as int] == x[j as int],
            !temp_b ==> forall|i: nat, j: nat| (0 <= i < k && 0 <= j < x.len()) ==> r[i as int] != x[j as int],
        decreases
            r.len() - k,
    {
        l = 0;
        tangent_missing = false;
        while l < x.len() && !tangent_missing && k < r.len()
            invariant
                0 <= l && l <= x.len(),
                temp_b ==> exists|i: nat, j: nat| 0 <= i < r.len() && 0 <= j < x.len() && r[i as int] == x[j as int],
                !temp_b ==> forall|i: nat| 0 <= i < l ==> r[k as int] != x[i as int],
                tangent_missing ==> l == x.len(),
            decreases
                x.len() - l,
        {
            assert(l < x.len());
            if r[k] == x[l] {
                temp_b = true;
            }
            if l == x.len() - 1 && r[k] < x[l] {
                tangent_missing = true;
            }
            l = l + 1;
        }
        k = k + 1;
    }
    temp_b
}

fn main() {}
} // verus!

