use vstd::prelude::*;
use vstd::seq::*;

verus! {

fn find_max(a: &Vec<i32>) -> (max_idx: usize)
    requires
        a.len() > 0,
    ensures
        0 <= max_idx < a.len(),
        forall|i: nat| 0 <= i < a.len() ==> a[max_idx as int] >= a[i as int],
{

answer:
let mut max_idx: usize = 0;
    let mut i: usize = 1;
    while i < a.len()
        invariant
            1 <= i <= a.len(),
            0 <= max_idx < i,
            forall|j: nat| 0 <= j < i ==> a[max_idx as int] >= a[j as int],
        decreases a.len() - i,
    {
        if a[i] > a[max_idx] {
            max_idx = i;
        }
        i = i + 1;
    }
    return max_idx;
}

fn main() {
    let arr: Vec<i32> = vec![1, 1, 25, 7, 2, -2, 3, 3, 20];
    let idx: usize = find_max(&arr);

    assert(forall|i: nat| 0 <= i < arr.len() ==> arr[idx as int] >= arr[i as int]);
    assert(idx == 2);
    assert(arr[idx as int] == 25);
}

} // verus!

