    ensures res@ == a@.filter(|x: u32| x % 2 != 0)
{

answer:
let mut res: Vec<u32> = Vec::new();
    let input_len = a.len();

    assert(a@.take(0int).filter(|x: u32| x % 2 != 0) == Seq::<u32>::empty());
    let mut index = 0;
    while index < a.len()
        invariant
            0 <= index <= a.len(),
            res@ == a@.take(index as int).filter(|x: u32| x % 2 != 0),
        decreases a.len() - index
    {
