            forall|k: int| 0 <= k < b.len() ==> b[k] as int == seq_sum(a@.subrange(0, k + 1)),
            i == 0 ==> acc == 0,
            i > 0 ==> acc as int == seq_sum(a@.subrange(0, i as int)),
    {
        acc = acc + a[i] as u64;
        b.push(acc);
    }
    b
}

question:
fn filter_nonnegative(a: &[i32]) -> (b: Vec<i32>)
    ensures
        forall|i: int| 0 <= i < b.len() ==> b[i] >= 0,
        forall|x: i32| b@.contains(x) ==> a@.contains(x),
{

answer:
{
    let mut b: Vec<i32> = Vec::new();
    for i in 0..a.len()
        invariant
            0 <= i <= a.len(),
            forall|k: int| 0 <= k < b.len() ==> b[k] >= 0,
            forall|x: i32| b@.contains(x) ==> a@.subrange(0, i as int).contains(x),
    {
        if a[i] >= 0 {
            b.push(a[i]);
        }
    }
    b
}

{
    let mut out: Vec<i32> = Vec::new();
    let mut i: usize = 0;
    let mut j: usize = 0;
    while i < a.len() || j < b.len()
        invariant
            0 <= i <= a.len(),
            0 <= j <= b.len(),
            out.len() == i + j,
            forall|x: int, y: int| 0 <= x < y < out.len() ==> out[x] <= out[y],
        decreases (a.len() - i) + (b.len() - j)
    {
        if j == b.len() || (i < a.len() && a[i] <= b[j]) {
            out.push(a[i]);
            i = i + 1;
        } else {
            out.push(b[j]);
            j = j + 1;
        }
    }
    out
}

{
    let mut left: usize = 0;
    let mut right: usize = a.len();
    while left < right
        invariant
            0 <= left <= right <= a.len(),
            forall|i: int| 0 <= i < left ==> a[i],
            forall|i: int| right <= i < a.len() ==> !a[i],
        decreases right - left
    {
        let mid = left + (right - left) / 2;
        if a[mid] {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    left
}

