use vstd::hash_set::HashSetWithView;
use vstd::std_specs::hash::axiom_u8_obeys_hash_table_key_model;

verus! {
broadcast use axiom_u8_obeys_hash_table_key_model;

fn has_duplicate_byte(s: &Vec<u8>) -> (r: bool)
    ensures
        r <==> exists|i: int, j: int| 0 <= i < j < s.len() && s[i] == s[j]
{

answer:
let mut seen = HashSetWithView::new();
    for i in 0..s.len()
        invariant
            forall|x: u8| seen@.contains(x) <==> exists|k: int| 0 <= k < i && s[k] == x,
    {
        if seen@.contains(s[i]) {
            return true;
        }
        seen.insert(s[i]);
    }
    false
}
}

