fn remove_consecutive_duplicates(a: &[i32]) -> (b: Vec<i32>)
    ensures
        forall|i: int| 0 <= i < b.len() - 1 ==> b[i] != b[i + 1],
        b.len() <= a.len(),
{

answer:
{
    let mut b: Vec<i32> = Vec::new();
    for i in 0..a.len()
        invariant
            0 <= i <= a.len(),
            forall|k: int| 0 <= k < b.len() - 1 ==> b[k] != b[k + 1],
            b.len() <= i,
    {
        if b.len() == 0 || b[b.len() - 1] != a[i] {
            b.push(a[i]);
        }
    }
    b
}

