fn interleave_equal(a: &[i32], b: &[i32]) -> (out: Vec<i32>)
    requires a.len() == b.len(),
    ensures out.len() == 2 * a.len(),
{

answer:
{
    let mut out: Vec<i32> = Vec::new();
    for i in 0..a.len()
        invariant
            0 <= i <= a.len(),
            out.len() == 2 * i,
    {
        out.push(a[i]);
        out.push(b[i]);
    }
    out
}
